let contentType = "movies";
if (window.location.href.includes("vodshow")) {
	contentType = "series";
}

window.addEventListener(
	"load",
	function () {
		this.setTimeout(function () {
			if (!window.location.href.includes("autoupdate=true")) {
				let targetData = contentType == "movies" ? moviesData[0] : seriesData[0];
				console.log(targetData);
                let jsonData = JSON.parse((document.getElementsByClassName("for_jsoneditor")).data.innerText)
                console.log(jsonData)
                let releaseYear = jsonData.releaseYear
                let title = jsonData.name;
                let rating = jsonData.rating;
                let ratingObject = document.getElementById("id_rating")
                let targetContent = targetData[title]
                console.log(targetContent)
                if(!targetContent || ratingObject.value != "N") {
                    console.log("Failed to update content")
                    return;
                }

                console.log("Updated content")

                ratingObject.value = targetContent.contentRating
			}
		}, 500);
	},
	false
);

